async function _fgetClustersSequence(req) {
    let locationId = req.data.LOCATION_ID;
    let productId = req.data.PRODUCT_ID;
    let modelProfile = req.data.MODEL_PROFILE;
    let clusterId = req.data.CLUSTER_ID;

    let sqlQuery =  ' SELECT LOCATION_ID, PRODUCT_ID, SOURCE_CLUSTER_ID, TARGET_CLUSTER_ID, DISTANCE ' +
                    ' FROM CP_AHC_CLUSTER_DISTANCES WHERE  1=1 ';

    if ( (locationId != undefined) &&
         (locationId != '') )
        sqlQuery += ' AND LOCATION_ID =  ' + "'" + locationId + "'";
    if ( (productId != undefined) &&
         (productId != '') )
        sqlQuery +=  ' AND PRODUCT_ID =  ' + "'" + productId + "'";
    if ( (clusterId != undefined) &&
        (clusterId != '') )
        sqlQuery +=  ' AND SOURCE_CLUSTER_ID  =  ' + "'" + clusterId + "'";
    if ( (modelProfile != undefined) &&
         (modelProfile != '') )
        sqlQuery +=  ' AND MODEL_PROFILE  =  ' + "'" + modelProfile + "'";

    sqlQuery+= ` ORDER BY SOURCE_CLUSTER_ID, DISTANCE `;
    console.log(" _getClustersSequence sqlQuery ", sqlQuery);
        
    let queryResult = await cds.run(sqlQuery);
    if(queryResult.length>0)
    {
        return  JSON.stringify(queryResult);
    }
}


async function _fgetClustersQty(req) {

    let locationId = req.data.LOCATION_ID;
    let productId = req.data.PRODUCT_ID;
    let clusterId = req.data.CLUSTER_ID;
    let modelProfile = req.data.MODEL_PROFILE;
    let startDate = req.data.START_DATE;
    let endDate = req.data.END_DATE;
    let clusterQtyType = req.data.QTY_TYPE;
    console.log("clusterQtyType", clusterQtyType);

    let locProdsSql = 'SELECT DISTINCT '

    if ( (locationId != undefined) &&
        (locationId == '') )
        locProdsSql += ' LOCATION_ID, ';
    if ( (productId != undefined) &&
        (productId == '') )
        locProdsSql += ' PRODUCT_ID ';

    locProdsSql =   locProdsSql + ' FROM CP_V_AHC_CLUSTERS_SORTED_COMBINED ';
    console.log(" locProdsSql", locProdsSql);
    if( (locationId == '') || 
        (productId == '') )
    {
        let locProdResults = await cds.run(locProdsSql);
        if(locProdResults.length>0)
        {
            return  JSON.stringify(locProdResults);
        }
    }

    let sqlQtyType = '';

    if ( (clusterQtyType != undefined) )
    {
        // ACTUALS_HISTORY = 1
        if ( (clusterQtyType === 1) ||
             (clusterQtyType === '') )
        {
            sqlQtyType +=  ', SUM(DEMAND) AS QUNATITY ';
        }
    }

    let sqlQuery =  ' SELECT LOCATION_ID, PRODUCT_ID, CLUSTER_ID, MODEL_PROFILE, ' +
                    ' UNIQUE_ID, C1, C2, C3, C4, C5, C6, C7, C8, C9, C10, C11, C12, ' +
                    ' C13, C14, C15, C16, C17, C18, C19, C20, C21, C22, C23, C24, C25, C26, C27, C28, C29, C30 , ' +
                    ' NC1, NC2, NC3, NC4, NC5, NC6, NC7, NC8, NC9, NC10, NC11, NC12, ' +
                    ' NC13, NC14, NC15, NC16, NC17, NC18, NC19, NC20, NC21, NC22, NC23, NC24, ' +
                    ' NC25, NC26, NC27, NC28, NC29, NC30 ' +
                    sqlQtyType +
                    ' FROM CP_V_AHC_CLUSTERS_SORTED_COMBINED WHERE  1=1 ';

    if ( (locationId != undefined) &&
         (locationId != '') )
        sqlQuery += ' AND LOCATION_ID =  ' + "'" + locationId + "'";
    if ( (productId != undefined) &&
         (productId != '') )
        sqlQuery +=  ' AND PRODUCT_ID =  ' + "'" + productId + "'";
    if ( (clusterId != undefined) &&
        (clusterId != '') )
       sqlQuery +=  ' AND CLUSTER_ID =  ' + "'" + clusterId + "'";
    if ( (startDate != undefined) &&
        (startDate != '') )
        sqlQuery +=  ' AND START_DATE  >=  ' + "'" + startDate + "'";
    if ( (endDate != undefined) &&
        (endDate != '') )
        sqlQuery +=  ' AND END_DATE  <=  ' + "'" + endDate + "'";
    if ( (modelProfile != undefined) &&
         (modelProfile != '') )
        sqlQuery +=  ' AND MODEL_PROFILE  =  ' + "'" + modelProfile + "'";
    

    sqlQuery+=  ' GROUP BY LOCATION_ID, PRODUCT_ID, CLUSTER_ID, MODEL_PROFILE, ' +
                    ' UNIQUE_ID, C1, C2, C3, C4, C5, C6, C7, C8, C9, C10, C11, C12, ' +
                    ' C13, C14, C15, C16, C17, C18, C19, C20, C21, C22, C23, C24, C25, C26, C27, C28, C29, C30 , ' +
                    ' NC1, NC2, NC3, NC4, NC5, NC6, NC7, NC8, NC9, NC10, NC11, NC12, ' +
                    ' NC13, NC14, NC15, NC16, NC17, NC18, NC19, NC20, NC21, NC22, NC23, NC24, ' +
                    ' NC25, NC26, NC27, NC28, NC29, NC30 ';
    sqlQuery+=  ' ORDER BY LOCATION_ID, PRODUCT_ID, CLUSTER_ID, MODEL_PROFILE, ' +
                    ' C1, C2, C3, C4, C5, C6, C7, C8, C9, C10, C11, C12, ' +
                    ' C13, C14, C15, C16, C17, C18, C19, C20, C21, C22, C23, C24, C25, C26, C27, C28, C29, C30 , ' +
                    ' NC1, NC2, NC3, NC4, NC5, NC6, NC7, NC8, NC9, NC10, NC11, NC12, ' +
                    ' NC13, NC14, NC15, NC16, NC17, NC18, NC19, NC20, NC21, NC22, NC23, NC24, ' +
                    ' NC25, NC26, NC27, NC28, NC29, NC30 ';
    console.log(" fgetClustersQty sqlQuery ", sqlQuery);
        
    let queryResult = await cds.run(sqlQuery);
    if(queryResult.length>0)
    {
        return  JSON.stringify(queryResult);
    }
}

