async function _postPurgePredictionModels(req,Location,Product,groupId,Type)
{
    var options;
    let username = conn_params.uid;
    let password = conn_params.pwd;
    // var auth = "Basic " + new Buffer(username + ":" + password).toString("base64");
    //For Oauth 2.0 we need to add authorization
    var auth =  await GenFunctions.getAuthorization();

    var baseUrl = req.headers['x-forwarded-proto'] + '://' + req.headers.host; 
    // var baseUrl = 'http' + '://' + req.headers.host;
	url =  baseUrl + '/pal/purgePredictionModels';
    
    options = {
        'method': 'POST',
        'url': url,
        'headers': {
            'Content-Type': 'application/json',
            'Authorization' : auth
    },
    'timeout': purgePredmodelsTimeout,

    body: JSON.stringify({vcRulesList :[{
        "Product": Product,
        "Location": Location,
        "GroupID" : groupId,
        "Type": Type
    }]})

    };
    

    let ret_response ="";

    console.log('_postPurgePredictionModels Request Time = ', new Date());

    await rp(options)
    .then(function (response) {
        console.log('_postPurgePredictionModels Response Time = ', new Date());
        ret_response = response;
        
    })
    .catch(function (err) {
       console.log('_postPurgePredictionModels - Error ');
       ret_response = err;

    });

}

async function _postRegressionRequest(req,url,paramsObj,numChars,dataObj,modelType,vcRuleListObj)
{
    var request = require('request');
    var options;
    let username = conn_params.uid;
    let password = conn_params.pwd;
    // var auth = "Basic " + new Buffer(username + ":" + password).toString("base64");
    //For Oauth 2.0 we need to add authorization
    var auth =  await GenFunctions.getAuthorization();

    if (modelType == 'HGBT')
    {

        options = {
            'method': 'POST',
            'url': url,
            'headers': {
                'Authorization' : auth,
                'Content-Type': 'application/json'
        },
		'timeout': regressionTimeout,
        body: JSON.stringify({
            "Product": vcRuleListObj[0].Product,
            "Location": vcRuleListObj[0].Location,
            "modelVersion" : vcRuleListObj[0].modelVersion,
            "regressionParameters": paramsObj,
            "hgbtType": numChars,
            "regressionData": dataObj
        })

        };
    }
    else if(modelType == 'RDT')
    {

        options = {
            'method': 'POST',
            'url': url,
            'headers': {
                'Authorization' : auth,
                'Content-Type': 'application/json'
        },
		'timeout': regressionTimeout,
        body: JSON.stringify({
            "Product": vcRuleListObj[0].Product,
            "Location": vcRuleListObj[0].Location,
            "modelVersion" : vcRuleListObj[0].modelVersion,
            "regressionParameters": paramsObj,
            "rdtType": numChars,
            "regressionData": dataObj
        })

        };
    }
    else if(modelType == 'AUTOML')
    {

        options = {
            'method': 'POST',
            'url': url,
            'headers': {
                'Authorization' : auth,
                'Content-Type': 'application/json'
        },
		'timeout': regressionTimeout,
        body: JSON.stringify({
            "Product": vcRuleListObj[0].Product,
            "Location": vcRuleListObj[0].Location,
            "modelVersion" : vcRuleListObj[0].modelVersion,
            "regressionParameters": paramsObj,
            "automlType": numChars,
            "regressionData": dataObj
        })

        };
    }
    else if (modelType == 'MLR')
    {
        options = {
            'method': 'POST',
            'url': url,
            'headers': {
                'Authorization' : auth,
                'Content-Type': 'application/json'
        },
		'timeout': regressionTimeout,
        body: JSON.stringify({
            "Product": vcRuleListObj[0].Product,
            "Location": vcRuleListObj[0].Location,
            "modelVersion" : vcRuleListObj[0].modelVersion,
            "regressionParameters": paramsObj,
            "mlrType": numChars,
            "regressionData": dataObj
        })

        };
    }
    else if (modelType == 'VARMA')
    {
        options = {
            'method': 'POST',
            'url': url,
            'headers': {
                'Authorization' : auth,
                'Content-Type': 'application/json'
        },
		'timeout': regressionTimeout,
        body: JSON.stringify({
            "Product": vcRuleListObj[0].Product,
            "Location": vcRuleListObj[0].Location,
            "modelVersion" : vcRuleListObj[0].modelVersion,
            "controlParameters": paramsObj,
            "varmaType": numChars,
            "varmaData": dataObj
        })

        };
    }


    let ret_response ="";
    let error = false;

    console.log('_postRegressionRequest Request Time = ', new Date());

    await rp(options)
    .then(function (response) {
        console.log('_postRegressionRequest Response Time = ', new Date());
        // console.log('Response   = ', response);
        // ret_response = JSON.parse(response);
        ret_response = response;
        
    })
    .catch(function (err) {
       console.log('_postRegressionRequest - Error ');
       ret_response = err;
       error = true;

    });
	
	
	// console.log('ret_response:', ret_response); // Print the response status code if a response was received
	if (error) {
		let errObj = {};
		errObj["success"] = false;
		errObj["message"] = "Generate Models Job Failed with ERROR : " + error;


		if (req.headers['x-sap-job-id'] > 0)
		{
			const scheduler = getJobscheduler(req);

			var updateReq = {
				jobId: req.headers['x-sap-job-id'],
				scheduleId: req.headers['x-sap-job-schedule-id'],
				runId: req.headers['x-sap-job-run-id'],
				data : errObj
				};


			scheduler.updateJobRunLog(updateReq, function(err, result) {
			if (err) {
				return console.log('Error updating run log: %s', err);
			}

			});
		}

		throw new Error(error);
	}

	if (error == false)
	{


		let responseData = JSON.parse(ret_response);

		var cqnQuery = "";
		if (modelType == 'HGBT')
		{
			cqnQuery = {UPSERT:{ into: { ref: ['CP_PALGENREGRESSIONMODELS'] }, entries: [

				{   regressionsID: responseData.value[0].hgbtID, 
					createdAt : responseData.value[0].createdAt, 
					modelType : modelType,
					vcRulesList : vcRuleListObj
				}
			]}}
		}
		else if (modelType == 'RDT')
		{

			  cqnQuery = {UPSERT:{ into: { ref: ['CP_PALGENREGRESSIONMODELS'] }, entries: [

				  {   regressionsID: responseData.value[0].rdtID, 
					  createdAt : responseData.value[0].createdAt, 
					  modelType : modelType,
					  vcRulesList : vcRuleListObj
				  }
			  ]}}
		}
		else if (modelType == 'AUTOML')
		{
            console.log("regressionsID modelType ", modelType);
            // console.log("regressionsID ret_response ", ret_response);
            
			  cqnQuery = {UPSERT:{ into: { ref: ['CP_PALGENREGRESSIONMODELS'] }, entries: [
				  {   regressionsID: responseData.value[0].automlID, 
					  createdAt : responseData.value[0].createdAt, 
					  modelType : modelType,
					  vcRulesList : vcRuleListObj
				  }
			  ]}}
		}
		else if (modelType == 'MLR')
		{
			cqnQuery = {UPSERT:{ into: { ref: ['CP_PALGENREGRESSIONMODELS'] }, entries: [
				{   regressionsID: responseData.value[0].mlrID, 
					createdAt : responseData.value[0].createdAt, 
					modelType : modelType,
					vcRulesList : vcRuleListObj
				}
			]}}
		}
		else if (modelType == 'VARMA')
		{
			cqnQuery = {UPSERT:{ into: { ref: ['CP_PALGENREGRESSIONMODELS'] }, entries: [
				{   regressionsID: responseData.value[0].varmaID, 
					createdAt : responseData.value[0].createdAt, 
					modelType : modelType,
					vcRulesList : vcRuleListObj
				}
			]}}
		}

		// await cds.run(cqnQuery);
		try {
			await cds.run(cqnQuery);
		}
		catch (exception) {
			console.log("cqnQuery ", cqnQuery);
			throw new Error(exception.toString());
		}
	}
	else
	{
		console.error('_postRegressionRequest - error:'); // Print the error if one occurred

		let errorObj = {};
		errorObj["success"] = false;

		errorObj["message"] = 'ERROR Generate Models Response error : ' + ' AT ' + new Date() +
								 '\n Response Details :' + 
								 '\n Location : ' + vcRuleListObj[0].Location +
								 '\n Product : ' + vcRuleListObj[0].Product +
								 '\n Type : ' + vcRuleListObj[0].Type +
								 '\n Models generation Response : ' + JSON.parse(ret_response.body);

		if (req.headers['x-sap-job-id'] > 0)
		{
			const scheduler = getJobscheduler(req);

			var updateReq = {
				jobId: req.headers['x-sap-job-id'],
				scheduleId: req.headers['x-sap-job-schedule-id'],
				runId: req.headers['x-sap-job-run-id'],
				data : errorObj
				};

			scheduler.updateJobRunLog(updateReq, function(err, result) {
			if (err) {
				return console.log('Error updating run log: %s', err);
			}


			});
		}
	}
}

