async function _genPcaCategoricalComps(req, reqLocation, reqProduct, pcaCatUniqueId, prpidsUniqueId) {

    let uuid = pcaCatUniqueId; 
    await _genPcaCatSByLocProduct(req, reqLocation, reqProduct, pcaCatUniqueId);

    const pcaCatStatusIntervalId = setInterval(async ()=>{

        let sqlStr = 'SELECT STATUS, STATUS_MESSAGE FROM  CP_PAL_PROCESS_STATUS WHERE ' +
                    ' UNIQUE_ID = ' + "'" + prpidsUniqueId + "'" +
                    ' AND PROCESS_NAME = ' + "'" + 'CLUSTERING' + "'";
        console.log("CHECK PRPID STATUS REQUEST CP_PAL_PROCESS_STATUS sqlStr ", sqlStr);

        let prpidsStatus;
        try {
            prpidsStatus = await cds.run(sqlStr);
        }
        catch (exception) {
            console.log("sqlStr exception ", sqlStr);
            throw new Error(exception.toString());
        }
        console.log("_genPcaCategoricalComps prpidsUniqueId ", prpidsUniqueId, " prpidsStatus Status ", prpidsStatus);

        if(prpidsStatus.length > 0)
        {    
            if ( (prpidsStatus[0].STATUS === 'ERROR') ||
                 (prpidsStatus[0].STATUS === 'NOPIDS') )
            {               
                    
                clearInterval(pcaCatStatusIntervalId);
                console.log('Terminating  _genPcaCategoricalComps due to Error in PRPIDS generation for ', uuid); 
                
            }
        }

        sqlStr = 'SELECT STATUS, STATUS_MESSAGE FROM  CP_PAL_PROCESS_STATUS WHERE ' +
                        ' UNIQUE_ID = ' + "'" + uuid + "'" +
                        ' AND PROCESS_NAME = ' + "'" + 'PCACAT' + "'";
                        console.log("PCACAT STATUS REQUEST CP_PAL_PROCESS_STATUS sqlStr ", sqlStr);

        let pcaCatStatus;
        try {
            pcaCatStatus = await cds.run(sqlStr);
        }
        catch (exception) {
            console.log("sqlStr exception ", sqlStr);
            throw new Error(exception.toString());
        }
        console.log("_genPcaCategoricalComps uniqueId ", uuid, " pcaCatStatus Status ", pcaCatStatus);

        if(pcaCatStatus.length > 0)
        {

            if ( (pcaCatStatus[0].STATUS === 'COMPLETED') ||
                (pcaCatStatus[0].STATUS === 'ERROR') ) 
            {               
                   
                clearInterval(pcaCatStatusIntervalId);
                console.log(' _genPcaCategoricalComps completed for ', uuid); 
                
            }
            if(pcaCatStatus[0].STATUS === 'COMPLETED')
            {
                sqlStr = 'UPSERT "CP_PAL_PROCESS_STATUS" VALUES (' +
                            "'" + uuid + "'" + "," +
                            "'" + 'PCACAT' + "'" + "," +
                            "'" +  reqLocation + "'" + "," +
                            "'" +  reqProduct + "'" + "," +
                            "'" + 'COMPLETED' + "'" +  "," +
                            "'" + ' PCACAT GENERATION COMPLETED SUCCESSFULLY ' + "'" + ')' + ' WITH PRIMARY KEY';  

                try {
                    sqlResults = await cds.run(sqlStr);
                }
                catch (exception) {
                    console.log("sqlStr ", sqlStr);
                    throw new Error(exception.toString());
                }
            }
            else if (pcaCatStatus[0].STATUS === 'ERROR')
            {
                sqlStr = 'UPSERT "CP_PAL_PROCESS_STATUS" VALUES (' +
                            "'" + uuid + "'" + "," +
                            "'" + 'PCACAT' + "'" + "," +
                            "'" +  reqLocation + "'" + "," +
                            "'" +  reqProduct + "'" + "," +
                            "'" + 'ERROR' + "'" +  "," +
                            "'" + ' PCACAT GENERATION ERROR DUE TO CLUSTERING ERROR ' + "'" + ')' + ' WITH PRIMARY KEY';  

                try {
                    sqlResults = await cds.run(sqlStr);
                }
                catch (exception) {
                    console.log("sqlStr ", sqlStr);
                    throw new Error(exception.toString());
                }
                console.log(' PCACAT Errored for ', uuid); 
            } 
        }

    },2000);
}

