// Function to compute Weighted Gower's Distance Matrix
async function updateGowerDistanceMatrix(location, product, data, featureWeights) {
    // console.log(" updateGowerDistanceMatrix location ", location, "product ", product, "data", data, "featureWeights ", featureWeights);
    const n = data.length;
    const distanceMatrix = math.zeros(n, n)._data;
    let tableObj = [];
    let sqlStr = 'DELETE FROM CP_PRECALCULATED_DISTANCE_DATA ' +
                    ' WHERE PRODUCT_ID =' + "'" + product + "'" + 
                    ' AND LOCATION_ID =' + "'" + location + "'";
    try {
        await cds.run(sqlStr);
    }
    catch (exception) {
        console.log("updateGowerDistanceMatrix sqlStr ", sqlStr);
        throw new Error(exception.toString());
    }

    let numInsertions = 0;

    for (let i = 0; i < n; i++) 
    {
        for (let j = i; j < n; j++) {
            if (i === j) {
            distanceMatrix[i][j] = 0;

            continue;
            }

            let weightedDissimilarity = 0;
            let totalWeight = 0;

            // Iterate over features to compute dissimilarity
            for (const feature in featureWeights) {
                const weight = featureWeights[feature];
                totalWeight += weight;

                const value1 = data[i][feature];
                const value2 = data[j][feature];

                // Categorical dissimilarity: 1 if different, 0 if same
                const dissimilarity = value1 === value2 ? 0 : 1;

                weightedDissimilarity += dissimilarity * weight;
                // console.log(" i ", i, "j ", j, "LEFT_POINT ", data[i].UNIQUE_ID, "RIGHT_POINT ", data[j].UNIQUE_ID);
            }

            // Normalize by total weight
            distanceMatrix[i][j] = weightedDissimilarity / totalWeight;
            let rowObj = {"LOCATION_ID":location, "PRODUCT_ID": product, 
                    "LEFT_POINT":data[i].UNIQUE_ID, "RIGHT_POINT":data[j].UNIQUE_ID, 
                    "DISTANCE":(distanceMatrix[i][j]).toFixed(4)};

            // console.log("i ", i, "j ", j, "rowObj ", rowObj)
            tableObj.push(rowObj);
            if(tableObj.length % 5000 === 0)
            {

                let cqnQuery = {UPSERT:{ into: { ref: ['CP_PRECALCULATED_DISTANCE_DATA'] }, entries:  tableObj }};

                try {
                    await cds.run(cqnQuery);
                    numInsertions++;
                    // await cds.COMMIT();

                    // await sleep(1000);
                }
                catch (exception) {
                    console.log("cqnQuery ", cqnQuery);
                    throw new Error(exception.toString());
                }
                // console.log("tableObj length ", tableObj.length, "resetting Table Obj ", " i ", i, "j ", j);
                tableObj = [];
            }
        }
    }

    // console.log("tableObj length ", tableObj.length);

    let cqnQuery = {UPSERT:{ into: { ref: ['CP_PRECALCULATED_DISTANCE_DATA'] }, entries:  tableObj }};
    if( tableObj.length > 0)
    {
        try {
            await cds.run(cqnQuery);
            numInsertions++;
            // await cds.COMMIT();
            // await sleep(1000);

        }
        catch (exception) {
            console.log("cqnQuery ", cqnQuery);
            throw new Error(exception.toString());
        }
    }

    // console.log("numInsertions ", numInsertions);
    // let offset = 0;
    // const batchSize = 5000;
    // let results = [];
    // let numBatches = 0;

    // while (true) {

        
    //     let sqlStrSuccessCheck = 'SELECT DISTINCT "LEFT_POINT", "RIGHT_POINT", "DISTANCE" FROM "CP_PRECALCULATED_DISTANCE_DATA"' +
    //                   ' WHERE "PRODUCT_ID" = ' + "'" +  product + "'" +  
    //                     ' AND "LOCATION_ID" =' + "'" +   location + "'" +
    //                     ' LIMIT ' + "'" + batchSize + "'" + 'OFFSET ' + "'" + offset + "'";
    //     console.log("sqlStrSuccessCheck ", sqlStrSuccessCheck)

    //     const batch = await cds.run(sqlStrSuccessCheck);
    //     console.log("batch ", batch)
    //     if (batch.length !== 0)
    //     {
    //         numBatches ++;
    //     } 
    //     console.log("numBatches ", numBatches)

    //     if(numInsertions === numBatches)
    //         break;
    //     // results = results.concat(batch); // or process batch
    //     // console.log("sqlStrSuccessCheck results ", results);
    //     offset += batchSize;
    // }


    return distanceMatrix;
}

