        paramsObj.push({"groupId":palGroupId, "paramName":"CATEGORICAL_VARIABLE", "intVal":null,"doubleVal": null, "strVal" : "C4"});
        paramsObj.push({"groupId":palGroupId, "paramName":"CATEGORICAL_VARIABLE", "intVal":null,"doubleVal": null, "strVal" : "C5"});
        paramsObj.push({"groupId":palGroupId, "paramName":"CATEGORICAL_VARIABLE", "intVal":null,"doubleVal": null, "strVal" : "C6"});
        paramsObj.push({"groupId":palGroupId, "paramName":"CATEGORICAL_VARIABLE", "intVal":null,"doubleVal": null, "strVal" : "C7"});
