 async function _getRuleListTypeForGenOptions(vcRulesList, modelType)
{


    var sqlStr ="";
    var ruleListObj = [];
    for (var i = 0; i < vcRulesList.length; i++)
    {
        
        results = [];


        sqlStr = 'SELECT * FROM "CP_PAL_PROFILEMETH_PARA"' +
                ' WHERE "PROFILE" = ' + "'" + vcRulesList[i].profile + "'" +
                ' AND "METHOD" = ' + "'" + modelType + "'";
        // console.log(" _getRuleListTypeForGenOptions ", sqlStr);
        // results = await cds.run(sqlStr);
        try {
            results = await cds.run(sqlStr);
        }
        catch (exception) {
            console.log("sqlStr ", sqlStr);
            throw new Error(exception.toString());
        }
        if (results.length > 0)
        {
            ruleListObj.push({"Location":vcRulesList[i].Location, 
                            "Product":vcRulesList[i].Product, 
                            "GroupID":vcRulesList[i].GroupID,
                            "Type":vcRulesList[i].Type, 
                            "modelVersion":vcRulesList[i].modelVersion, 
                            "modelType":results[0].METHOD, 
                            "profileID":results[0].PROFILE, 
                            "override":vcRulesList[i].override,
                            "version":vcRulesList[idx].version,
                            "scenario":vcRulesList[idx].scenario});
        }
    }


    return ruleListObj;

}

async function _getParamsObjForGenOptions(vcRulesList)
{

    var sqlStr = "";
    var results= [];
    var paramsObj = [];
    var method = 0;
    for (var i = 0; i < vcRulesList.length; i++)
    {


        sqlStr = 'SELECT * FROM "CP_PAL_PROFILEMETH_PARA"' +
                    ' WHERE "PROFILE" = ' + "'" + vcRulesList[i].profileID + "'"; 

        // results = await cds.run(sqlStr);
        try {
            results = await cds.run(sqlStr);
        }
        catch (exception) {
            console.log("sqlStr ", sqlStr);
            throw new Error(exception.toString());
        }
        if (results.length > 0)
        {
            method = results[0].METHOD;
        }

        if (method != 0)
        {
            let palGroupId =  vcRulesList[i].profileID + '#' + vcRulesList[i].Type + '#' +vcRulesList[i].GroupID + '#' + vcRulesList[i].Location + '#' + vcRulesList[i].Product;

            // console.log(" palGroupId ", palGroupId);
            for (let index=0; index<results.length; index++) 
            {
            
                paramsObj.push({"groupId":palGroupId, 
                                "paramName":results[index].PARA_NAME, 
                                "intVal":results[index].INTVAL,
                                "doubleVal": results[index].DOUBLEVAL, 
                                "strVal" : results[index].STRVAL});

            }

        }
    }

    return paramsObj;

}

async function _getDataObjForGenOptions(vcRulesList) {

    var sqlStr = "";
    var results= [];
    var dataObj = [];	
    console.log("_getDataObjForGenOptions vcRulesList length = ",vcRulesList.length);

    for (var i = 0; i < vcRulesList.length; i++)
    {     
   
        sqlStr = 'SELECT DISTINCT "LOCATION_ID", "PRODUCT_ID","' + vcConfigTimePeriod + '", "GROUP_ID", "GROUP_COUNT_RATE" ' +
                ' FROM "CP_VC_HISTORY_TS" WHERE "PRODUCT_ID" =' +
                "'" +  vcRulesList[i].Product + "'" +  
                ' AND "TYPE" = ' + "'" + vcRulesList[i].Type + "'" +
                ' AND "LOCATION_ID" =' + "'" +   vcRulesList[i].Location + "'" + 
                ' AND "GROUP_ID" =' + "'" +   vcRulesList[i].GroupID + "'" + 
                ' ORDER BY "' + vcConfigTimePeriod + '", "LOCATION_ID", "PRODUCT_ID" ASC';

        
        // console.log("vcRulesList[",i,"] = ",vcRulesList[i]);

        // console.log("_getDataObjForGenOptions sqlStr", sqlStr);
        try {
            results = await cds.run(sqlStr);
        }
        catch (exception) {
            console.log("sqlStr ", sqlStr);
            throw new Error(exception.toString());
        }
        // console.log("_getDataObjForGenModels sqlStr results", results);

        let yearWeek = (results[0].PERIOD_NUM).toString();
        let year = yearWeek.slice(0,4);
        let week = yearWeek.slice(4,6);
        // console.log("year  =", year, "week =", week);
        let startDate = await aesFuncs._getDateOfIsoWeek(Number(week),Number(year));
       

        let distinctPeriodIdx = 0;
        for (let index=0; index<results.length; index++) 
        {
            let palGroupId =  vcRulesList[i].profileID + '#' +  vcRulesList[i].Type + '#' + vcRulesList[i].GroupID + '#' + vcRulesList[i].Location + '#' + vcRulesList[i].Product;
            if(index > 0)
            { 
                yearWeek = (results[index].PERIOD_NUM).toString();
                year = yearWeek.slice(0,4);
                week = yearWeek.slice(4,6);
                let nextDate = await aesFuncs._getDateOfIsoWeek(Number(week),Number(year));
                distinctPeriodIdx = Math.round((nextDate - startDate) / (7 * 24 * 60 * 60 * 1000));
                // console.log("groupId",palGroupId,"index ", index, "startDate ", startDate, "nextDate ", nextDate, "Week# ", distinctPeriodIdx);
            }    
            dataObj.push({"groupId":palGroupId, "timestamp":distinctPeriodIdx+1,"value":results[index].GROUP_COUNT_RATE});
            // dataObj.push({"groupId":palGroupId, "timestamp":results[index].PERIOD_NUM,"value":results[index].GROUP_COUNT_RATE});
            // distinctPeriodIdx++;
            // console.log("timestamp =" ,distinctPeriodIdx, "palGroupId =", palGroupId);
        }

    }

    // console.log("dataObj = ", dataObj);
    return dataObj;
}



